  '[{"n":"★ Driver Gloves | Imperial Plaid (Factory New)","ch":0.000004},{"n":"★ Specialist Gloves | Field Agent (Factory New)","ch":0.000004545},{"n":"★ Hand Wraps | Leather (Factory New)","ch":0.000005},{"n":"★ Butterfly Knife | Rust Coat (Well-Worn)","ch":0.000007692},{"n":"★ Karambit | Rust Coat (Well-Worn)","ch":0.000008333},{"n":"★ M9 Bayonet | Rust Coat (Well-Worn)","ch":0.0000125},{"n":"★ Talon Knife | Rust Coat (Battle-Scarred)","ch":0.000016667},{"n":"AK-47 | Fuel Injector (Battle-Scarred)","ch":0.00005},{"n":"Sawed-Off | Медь (После полевых испытаний)","ch":0.000055556},{"n":"AWP | Азимов (Закалённое в боях)","ch":0.000058824},{"n":"MAC-10 | Медный Борре (После полевых испытаний)","ch":0.000058824},{"n":"★ Sport Gloves | Bronze Morph (Battle-Scarred)","ch":0.000066667},{"n":"XM1014 | Красная кожа (После полевых испытаний)","ch":0.000111111},{"n":"AK-47 | Азимов (Закалённое в боях)","ch":0.000111111},{"n":"Nova | Blaze Orange (Field-Tested)","ch":0.0002},{"n":"USP-S | Оранжевый анолис (После полевых испытаний)","ch":0.00025},{"n":"SSG 08 | Оранжевая филигрань (Немного поношенное)","ch":0.000285714},{"n":"P2000 | Woodsman (Battle-Scarred)","ch":0.000333333},{"n":"Galil AR | Orange DDPAT (Field-Tested)","ch":0.0004},{"n":"PP-Bizon | Rust Coat (Field-Tested)","ch":0.0004},{"n":"P90 | Shapewood (Battle-Scarred)","ch":0.001111111},{"n":"MP5-SD | Autumn Twilly (Field-Tested)","ch":0.0025},{"n":"CZ75-Auto | Green Plaid (Field-Tested)","ch":0.00625},{"n":"P2000 | Янтарный градиент (Прямо с завода)","ch":0.307699012},{"n":"AUG | Amber Fade (Field-Tested)","ch":0.159617804},{"n":"PP-Bizon | Fuel Rod (Field-Tested)","ch":0.153883063},{"n":"MAG-7 | Copper Coated (Field-Tested)","ch":0.14515796},{"n":"MP7 | Amberline (Field-Tested)","ch":0.137804295},{"n":"Five-SeveN | Осенняя чаща (После полевых испытаний)","ch":0.083536878}]'::jsonb, now())
on conflict (id) do update set name = excluded.name, price = excluded.price, img = excluded.img, accent = excluded.accent, block = excluded.block,
  sub = excluded.sub, items = excluded.items, updated_at = now();

select 'Деда Дед: предметов ' || (select jsonb_array_length(items) from public.custom_cases where id = 'dedaded')
  || ', сумма шансов ' || (select round(sum((e->>'ch')::numeric), 6) from public.custom_cases c, jsonb_array_elements(c.items) e where c.id = 'dedaded') as result;
